    /// <summary>
    /// Connects <paramref name="device"/> and reports what happened to <em>that</em> device.
    /// </summary>
    /// <returns>
    /// A result naming the device this call was given and the terminal status it reached. Callers
    /// must branch on this rather than on <see cref="ConnectionStatus"/>, which any concurrent
    /// attempt overwrites (issue #212).
    /// </returns>
    // @port: Daqifi.Desktop.ConnectionManager.Connect
    // Signature divergence: upstream returns void/Task and leaves callers to read ConnectionStatus.
    // This port returns the attempt's own result, because its callers can overlap (issue #212).
    public async Task<ConnectionAttemptResult> Connect(IStreamingDevice device)
    {
        var status = await RunConnectAttempt(device);

        // Publishing the shared field is the LAST thing the attempt does, so the value a caller
        // gets back cannot be a different device's. The field itself is still a race between
        // overlapping attempts — it is one field — which is exactly why it is no longer the answer.
        ConnectionStatus = status;
        return new ConnectionAttemptResult(device, status);
    }

    /// <summary>
    /// The connect itself, returning its own terminal status instead of publishing it. Every exit
    /// is a <c>return</c>, so no path can leave the result to be inferred from shared state.
    /// </summary>
    private async Task<DAQiFiConnectionStatus> RunConnectAttempt(IStreamingDevice device)
    {
        try
        {
            // Never let a user-initiated USB connect (or a discovery-driven one) open the COM port
            // while a firmware update is running: the device being flashed re-enumerates its USB-CDC
            // port mid-update, and Core's own JumpingToApp step reconnects it directly (not through
            // this method). A competing open here would steal the port out from under that reconnect
            // and strand the update in a JumpingToApp timeout even though the flash succeeded — the
            // exact failure in issue #738. WiFi connects are unaffected (different device path).
            // Core's reconnect calls the Core device's Connect() directly, so this gate can't block it.
            if (IsFirmwareUpdateInProgress && device.ConnectionType == ConnectionType.Usb)
            {
                AppLogger.Instance.Warning(
                    $"Refusing to connect USB device {device.Name} while a firmware update is in progress " +
                    "(the device reconnects itself after the flash).");
                return DAQiFiConnectionStatus.Error;
            }

            // Progress, not a result: this is the one write that is meant to be seen mid-flight.
            ConnectionStatus = DAQiFiConnectionStatus.Connecting;

            // Check for duplicate device before connecting
            var duplicate = CheckForDuplicateDevice(device);
            if (duplicate != null)
            {
                // No handler set (the state this class is in until the connection dialog installs
                // one): the duplicate is rejected without opening a second connection, and the user
                // still has the device they asked for.
                if (DuplicateDeviceHandler == null)
                {
                    return DAQiFiConnectionStatus.AlreadyConnected;
                }

                switch (await DuplicateDeviceHandler(duplicate))
                {
                    case DuplicateDeviceAction.KeepExisting:
                        return DAQiFiConnectionStatus.AlreadyConnected;
                    case DuplicateDeviceAction.Cancel:
                        return DAQiFiConnectionStatus.Disconnected;
                    case DuplicateDeviceAction.SwitchToNew:
                        // Disconnect refuses the device of a firmware update (issue #538). Keep it
                        // then, or the new connection would open beside the one the update uses.
                        if (IsDeviceBeingUpdated(duplicate.ExistingDevice))
                        {
                            AppLogger.Instance.Warning(
                                $"Keeping {duplicate.ExistingDevice.Name}: a firmware update is in progress on it.");
                            return DAQiFiConnectionStatus.AlreadyConnected;
                        }

                        // Disconnect the existing device and continue with connection
                        Disconnect(duplicate.ExistingDevice);
                        break;
                }
            }

            var isConnected = await Task.Run(() => device.Connect());
            if (!isConnected)
            {
                return DAQiFiConnectionStatus.Error;
            }

            // Check again after connection (in case serial number wasn't available before connect)
            if (CheckForDuplicateDevice(device) != null)
            {
                // Disconnect the device we just connected since it's a duplicate
                device.Disconnect();
                return DAQiFiConnectionStatus.AlreadyConnected;
            }

            // A transport that dies between device.Connect() returning and the loss handler going
            // live below is UNOBSERVABLE: there is no subscriber yet, and even with one the handler
            // would find the device not yet in ConnectedDevices and return. Subscribing earlier
            // therefore does not close this window — re-reading the device's own state does. Without
            // it, accepting a wrapper whose transport is already gone puts exactly the stale entry
            // into ConnectedDevices that this class now exists to remove, and reports it as a
            // successful connect. Release the transport Connect() opened rather than leaking its
            // handle for the process lifetime.
            if (!device.IsConnected)
            {
                AppLogger.Instance.Warning(
                    $"Device {device.DeviceDisplayName} connected but its transport was already gone " +
                    "before it could be accepted; reporting the connect as failed.");
                device.Disconnect();
                return DAQiFiConnectionStatus.Error;
            }

            ConnectedDevices.Add(device);

            // Only now: these events bridge to the Core device, which does not exist until
            // device.Connect() above has created it, and the teardown handler must not fire for a
            // device that has not been accepted into ConnectedDevices yet.
            SubscribeDeviceEvents(device);

            // @port-divergence: upstream awaits Task.Delay(1000) here.
            // No fixed settle here (#617). Upstream waited 1 s at this point (daqifi-desktop
            // 550fd16e) so that the device's first status message could fill in the firmware
            // version and serial number before "ConnectedDevices" was raised. device.Connect() now
            // waits for that condition itself: Core's InitializeAsync waits for the first status
            // message that reports channels and identifies the device (or throws
            // ChannelPopulationTimeoutException after its timeout) and reads the capability
            // document, and Connect() hydrates the metadata again before it returns. So the
            // version, serial number and channels are already known here, and a fixed wait only
            // delayed the user.
            //
            // Core can still report Lost between the !IsConnected check above and here, once the
            // loss handler is attached. The handler only POSTS its teardown to the UI thread, and
            // this continuation normally runs on that thread, so the teardown cannot have run yet:
            // the device is still in ConnectedDevices while its transport is gone. So read the
            // device's own state again, and if the transport is gone, run the same teardown now.
            // The queued teardown then finds the device gone and does nothing, so the device is
            // torn down once. A device that a firmware update is flashing is left to that update,
            // as the loss handler does.
            if (ConnectedDevices.Contains(device) && !device.IsConnected && !IsDeviceBeingUpdated(device))
            {
                TearDownDroppedDevice(device, $"{device.DeviceDisplayName} disconnected while it was connecting.");
            }

            // The loss handler can also have run already, when it runs on another thread than this
            // continuation (a caller that is not on the UI thread). Either way, the connect did not
            // leave a usable connection — publishing "Connected" here would put the shell back
            // into a connected state for a device that is gone, and SetDeviceContext below would
            // tag every later Sentry event with dead hardware. Treat it as an aborted connect. A
            // drop after this point is the loss handler's to report, like any other drop of a
            // connected device.
            //
            // Error rather than Disconnected because that is the status every other failure in this
            // method reports, and it is what keeps the connection dialog open
            // (ConnectionDialogViewModel:534) — reconnecting is exactly what the user does next. The
            // accurate, device-naming message still comes from the teardown's own notification.
            if (!ConnectedDevices.Contains(device))
            {
                AppLogger.Instance.Warning(
                    $"Device {device.DeviceDisplayName} dropped before its connect completed; " +
                    "reporting the connect as failed rather than connected.");
                return DAQiFiConnectionStatus.Error;
            }

            OnPropertyChanged("ConnectedDevices");

            var connectionType = device.ConnectionType == ConnectionType.Usb ? "usb" : "wifi";
            AppLogger.Instance.SetDeviceContext(
                device.DevicePartNumber,
                device.DeviceSerialNo,
                device.DeviceVersion,
                connectionType,
                ActiveChannelCount(device));
            AppLogger.Instance.AddBreadcrumb("device", $"Device connected: {device.Name} (S/N: {device.DeviceSerialNo}) via {connectionType}");

            return DAQiFiConnectionStatus.Connected;
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Failed to Connect in Connection");
            return DAQiFiConnectionStatus.Error;
        }
    }

    // @port: Daqifi.Desktop.ConnectionManager.Disconnect
    public void Disconnect(IStreamingDevice device)
    {
        // Issue #538: the firmware update uses this device's connection until it ends. A disconnect
        // during the update disposes the Core device under the write, the same failure the drop
        // paths avoid with this check (issue #738). The drawer already disables DISCONNECT; this
        // is the barrier for every other caller. ReconcileDeviceAfterUpdate disconnects after the update clears the
        // state, so it is not stopped here.
        if (RefuseDuringFirmwareUpdate(device, "disconnect"))
        {
            return;
        }

        var connectionType = device.ConnectionType == ConnectionType.Usb ? "usb" : "wifi";
        try
        {
            // Before the device's own teardown, while the Core device these events bridge to is
            // still alive to detach from.
            UnsubscribeDeviceEvents(device);
            device.Disconnect();
            ConnectedDevices.Remove(device);
            OnPropertyChanged("ConnectedDevices");

            AppLogger.Instance.AddBreadcrumb("device", $"Device disconnected: {device.Name} (S/N: {device.DeviceSerialNo}) via {connectionType}");

            if (ConnectedDevices.Count == 0)
            {
                AppLogger.Instance.ClearDeviceContext();
            }
            else
            {
                var remaining = ConnectedDevices[^1];
                var remainingType = remaining.ConnectionType == ConnectionType.Usb ? "usb" : "wifi";
                AppLogger.Instance.SetDeviceContext(
                    remaining.DevicePartNumber,
                    remaining.DeviceSerialNo,
                    remaining.DeviceVersion,
                    remainingType,
                    ActiveChannelCount(remaining));
            }
        }
        catch (Exception ex)
        {
            AppLogger.Instance.AddBreadcrumb("device", $"Device disconnect failed: {device.Name} (S/N: {device.DeviceSerialNo}) via {connectionType}", Common.Loggers.BreadcrumbLevel.Error);
            AppLogger.Instance.Error(ex, "Failed in Disconnect");
        }
    }

    // Downstream-only (mobile support): the mobile shell connects a device
    // directly over WiFi/TCP (DaqifiStreamingDevice.Connect) rather than through
    // Connect() above — which also drives serial duplicate-detection and a 1 s
    // settle that the mobile flow doesn't want. These let the mobile shell publish
    // the already-connected device into the shared ConnectedDevices list so the
    // projected pane VMs that observe it (DeviceLogsViewModel and future mobile
    // panes) see it and are notified. No upstream counterpart — the WPF app always
    // routes through Connect().
    public void RegisterConnectedDevice(IStreamingDevice device)
    {
        if (device is null || ConnectedDevices.Contains(device)) { return; }
        ConnectedDevices.Add(device);
        OnPropertyChanged(nameof(ConnectedDevices));

        // Diagnostics only — the mobile shell owns its own drop teardown. See
        // SubscribeDeviceDiagnostics for why ConnectionLost is deliberately not wired here.
        SubscribeDeviceDiagnostics(device);

        // Same enrichment Connect() applies. This is the path MOBILE connects through, and
        // without it every Sentry event from Android arrived with no device model, serial or
        // firmware attached — the desktop's crash reports carry all three, so mobile reports
        // were strictly harder to act on for no reason other than which method was called.
        EnrichTelemetry(() =>
        {
            var connectionType = device.ConnectionType == ConnectionType.Usb ? "usb" : "wifi";
            AppLogger.Instance.SetDeviceContext(
                device.DevicePartNumber,
                device.DeviceSerialNo,
                device.DeviceVersion,
                connectionType,
                ActiveChannelCount(device));
            AppLogger.Instance.AddBreadcrumb(
                "device", $"Device connected: {device.Name} (S/N: {device.DeviceSerialNo}) via {connectionType}");
        });
    }

    /// <summary>
    /// Runs Sentry enrichment so nothing it throws can escape into the device flow. Telemetry is
    /// not load-bearing: an exception here unwinds into UsbDeviceConnector's catch, which tears
    /// the device down and reports a SUCCESSFUL connect as a failure (audit #ec1ca58).
    /// <para>
    /// The catch is silent on purpose. The likeliest failure is AppLogger.Instance itself failing
    /// to construct (issue #127) — reporting that through AppLogger would throw again, which is
    /// exactly the trap this guard exists to avoid.
    /// </para>
    /// </summary>
    private static void EnrichTelemetry(Action enrich)
    {
        try { enrich(); }
        catch { /* telemetry must never break a connect or a teardown */ }
    }

    /// <summary>
    /// The channel count reported to Sentry as <c>daqifi.active_channels</c>. Single definition
    /// on purpose: the tag is set from several places (connect, unregister, stream start), and
    /// if they disagreed the tag would silently mean different things depending on which fired
    /// last. Counts every active channel on the device, not just the analog ones a given screen
    /// happens to be streaming.
    /// </summary>
    internal static int ActiveChannelCount(IStreamingDevice device)
    {
        // Never let telemetry break teardown. DataChannels is a plain List<IChannel> that Core's
        // background events rebuild wholesale (Clear + AddRange in RefreshChannels), so counting
        // it from the UI thread can throw "collection was modified". That throw would land after
        // the device was removed but before the context was set, stranding precisely the stale
        // tags this call exists to clear — and it would escape into callers, only some of which
        // wrap the unregister in a best-effort catch. A wrong channel count on one event is not
        // worth any of that.
        // Catch broadly on purpose. "Collection was modified" is only the tidiest way this
        // fails: List<T> writes _items, _size and _version without a barrier, so a read racing
        // AddRange's Grow can index past the end (IndexOutOfRangeException), and one landing
        // inside Clear's Array.Clear can hand the predicate a null channel (NullReferenceException)
        // — on ARM, which is every Android install. Narrowing to InvalidOperationException would
        // let those escape RegisterConnectedDevice into UsbDeviceConnector's outer catch, which
        // tears the device down and reports a SUCCESSFUL connect as a failure (audit #ec1ca58).
        try
        {
            return device.DataChannels?.Count(c => c.IsActive) ?? 0;
        }
        catch (Exception)
        {
            return 0;
        }
    }

    public void UnregisterConnectedDevice(IStreamingDevice device)
    {
        if (device is null || !ConnectedDevices.Remove(device)) { return; }
        OnPropertyChanged(nameof(ConnectedDevices));

        // Mirror of RegisterConnectedDevice. Runs before the caller's own device.Disconnect(),
        // while the Core device these events bridge to is still alive to detach from.
        UnsubscribeDeviceDiagnostics(device);

        EnrichTelemetry(() =>
        {
            AppLogger.Instance.AddBreadcrumb("device", $"Device unregistered: {device.Name}");

            // Mirror Disconnect()'s teardown. Sentry scope tags are global, so leaving them set
            // would tag every later event with a device that is no longer connected — mobile
            // tears down through here rather than Disconnect(), so a crash after a drop would
            // have named the dead device's model and serial. Wrong context is worse than none.
            if (ConnectedDevices.Count == 0)
            {
                AppLogger.Instance.ClearDeviceContext();
            }
            else
            {
                var remaining = ConnectedDevices[^1];
                AppLogger.Instance.SetDeviceContext(
                    remaining.DevicePartNumber,
                    remaining.DeviceSerialNo,
                    remaining.DeviceVersion,
                    remaining.ConnectionType == ConnectionType.Usb ? "usb" : "wifi",
                    ActiveChannelCount(remaining));
            }
        });
    }

    // @port: Daqifi.Desktop.ConnectionManager.Reboot
    public void Reboot(IStreamingDevice device)
    {
        // Issue #538: a reboot command in the middle of a firmware write. See Disconnect.
        if (RefuseDuringFirmwareUpdate(device, "reboot"))
        {
            return;
        }

        try
        {
            UnsubscribeDeviceEvents(device);
            device.Reboot();
            ConnectedDevices.Remove(device);
            OnPropertyChanged("ConnectedDevices");
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "Failed in Reboot");
        }
    }

    /// <summary>
    /// True, with a warning in the log, when <paramref name="device"/> is the device of the firmware
    /// update in progress, so a user command must not touch its connection (issue #538).
    /// </summary>
    // Downstream-only: no upstream counterpart.
    private bool RefuseDuringFirmwareUpdate(IStreamingDevice device, string action)
    {
        if (!IsDeviceBeingUpdated(device))
        {
            return false;
        }

        AppLogger.Instance.Warning(
            $"Refusing to {action} device {device.Name} while a firmware update is in progress on it.");
        return true;
    }

    // @port: Daqifi.Desktop.ConnectionManager.UpdateStatusString
    public void UpdateStatusString()
    {
        ConnectionStatusString = ConnectionStatus switch
        {
            DAQiFiConnectionStatus.Disconnected => "Disconnected",
            DAQiFiConnectionStatus.Connecting => "Connecting",
            DAQiFiConnectionStatus.Connected => "Connected",
            DAQiFiConnectionStatus.Error => "Error",
            DAQiFiConnectionStatus.AlreadyConnected => "AlreadyConnected",
            _ => "Error"
        };
    }

    #region Device Event Wiring
    /// <summary>
    /// Attaches every per-device event this class listens to. Kept as a single method with an exact
    /// mirror in <see cref="UnsubscribeDeviceEvents"/> so a newly wired event cannot be attached at
    /// connect and forgotten at teardown. Runs once the device has connected and been accepted into
    /// <see cref="ConnectedDevices"/>, which is also when the Core device behind these events exists.
    /// </summary>
    /// <remarks>
    /// Detach-then-attach rather than plain attach: <see cref="Connect"/> can be called twice on one
    /// device instance (a reconnect of a device the app never explicitly disconnected), and a second
    /// <c>+=</c> on the same handler would double every teardown and every log line. The detach is a
    /// no-op when nothing is attached.
    /// </remarks>
    // Internal rather than private so the teardown tests can put a device into the same wired
    // state Connect() leaves it in without a full connect per case; one test still goes through
    // Connect() itself to pin that this is what it calls.
    // @port: Daqifi.Desktop.ConnectionManager.SubscribeDeviceEvents
    internal void SubscribeDeviceEvents(IStreamingDevice device)
    {
        UnsubscribeDeviceEvents(device);

        device.ConnectionLost += OnDeviceConnectionLost;
        device.ErrorOccurred += OnDeviceErrorOccurred;
        device.SendFailed += OnDeviceSendFailed;
    }

    /// <summary>
    /// Detaches everything <see cref="SubscribeDeviceEvents"/> attached. Called from both teardown
    /// paths (<see cref="Disconnect(IStreamingDevice)"/> and <see cref="Reboot"/>) before the
    /// device's own teardown runs, while the underlying Core device is still alive to detach from.
    /// </summary>
    // @port: Daqifi.Desktop.ConnectionManager.UnsubscribeDeviceEvents
    internal void UnsubscribeDeviceEvents(IStreamingDevice device)
    {
        device.ConnectionLost -= OnDeviceConnectionLost;
        device.ErrorOccurred -= OnDeviceErrorOccurred;
        device.SendFailed -= OnDeviceSendFailed;
    }

    /// <summary>
    /// The diagnostics half of <see cref="SubscribeDeviceEvents"/>, for a device that reached
    /// <see cref="ConnectedDevices"/> through <see cref="RegisterConnectedDevice"/> — i.e. the
    /// mobile shell, which connects the device itself and owns its own teardown.
    /// </summary>
    /// <remarks>
    /// Deliberately excludes <see cref="IDevice.ConnectionLost"/>. Mobile already tears a dropped
    /// device down from its own <c>IsConnected</c> watcher
    /// (<c>MobileShellViewModel.HandleConnectionLost</c>), which does more than this class can — it
    /// also returns the shell to its device-list state. Subscribing the teardown handler here as
    /// well would mean two teardowns racing for one drop, for no gain. Gap B (the background
    /// failures being invisible) is not shell-specific, so those two events are wired on every
    /// platform.
    /// </remarks>
    private void SubscribeDeviceDiagnostics(IStreamingDevice device)
    {
        device.ErrorOccurred -= OnDeviceErrorOccurred;
        device.SendFailed -= OnDeviceSendFailed;

        device.ErrorOccurred += OnDeviceErrorOccurred;
        device.SendFailed += OnDeviceSendFailed;
    }

    /// <summary>Detaches what <see cref="SubscribeDeviceDiagnostics"/> attached.</summary>
    private void UnsubscribeDeviceDiagnostics(IStreamingDevice device)
    {
        device.ErrorOccurred -= OnDeviceErrorOccurred;
        device.SendFailed -= OnDeviceSendFailed;
    }

    /// <summary>
    /// Handles a device's <see cref="IDevice.ConnectionLost"/> event — Core detected a spontaneous
    /// transport drop (reboot, unplug, WiFi/TCP timeout) that this class would otherwise never
    /// learn about. Unsubscribes the device's channels, tears the connection down via
    /// <see cref="Disconnect(IStreamingDevice)"/>, and surfaces a notification naming the device
    /// and the reason.
    /// </summary>
    /// <remarks>
    /// <para>
    /// This is the one unplug detector for every transport (#441). For a USB device, Core's
    /// <c>SerialStreamTransport</c> polls for its port every second and reports two consecutive
    /// misses, or five consecutive I/O faults under traffic, as <c>ConnectionStatus.Lost</c>;
    /// <c>AbstractStreamingDevice</c> turns that into <see cref="IDevice.ConnectionLost"/>. The app
    /// used to run its own port watcher beside it (WMI on Windows, a port-list poll on macOS and
    /// Linux), and the two raced to this same teardown.
    /// </para>
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.OnDeviceConnectionLost
    private void OnDeviceConnectionLost(object? sender, ConnectionLostEventArgs e)
    {
        if (sender is not IStreamingDevice device)
        {
            return;
        }

        // Core raises this from its transport/reader thread. ConnectedDevices is mutated on the UI
        // thread by Connect/Disconnect, and NotifyConnection's change notification runs
        // DaqifiViewModel.UpdateUi synchronously, and done off-thread it can throw back into Core's
        // thread — so everything below has to be marshalled.
        MarshalToUiThread(() =>
        {
            // The device being flashed drops its transport when it reboots mid-update — an expected
            // part of the flash that Core reconnects itself. Tearing it down here would dispose the
            // Core device out from under Core's JumpingToApp reconnect and time the update out
            // (issue #738). ReconcileDeviceAfterUpdate handles a genuinely-failed reconnect.
            if (IsDeviceBeingUpdated(device))
            {
                return;
            }

            // Already torn down via another path — an explicit user disconnect racing this event.
            if (!ConnectedDevices.Contains(device))
            {
                return;
            }

            TearDownDroppedDevice(device, $"{device.DeviceDisplayName} disconnected ({e.Reason}).");
        });
    }

    /// <summary>
    /// The spontaneous-drop teardown: release the device's channels, disconnect and remove it,
    /// then raise the user-visible notification with a reason that names it.
    /// </summary>
    /// <remarks>
    /// Releasing the channels is not optional bookkeeping: left subscribed they stay in
    /// <c>LoggingManager</c> marked active for the process lifetime, still counting toward
    /// <c>CanToggleLogging</c> and still listed as live inputs for a device that is gone.
    /// <para>
    /// Ordered before <see cref="Disconnect(IStreamingDevice)"/> because
    /// <c>AbstractStreamingDevice.Disconnect</c> clears <c>DataChannels</c>, which
    /// <see cref="ChannelsToRelease"/> falls back to for a device that has no serial number —
    /// after the disconnect there would be nothing left for that fallback to enumerate.
    /// </para>
    /// </remarks>
    /// <param name="device">The device whose connection went away.</param>
    /// <param name="reason">User-facing sentence naming the device and what happened.</param>
    private void TearDownDroppedDevice(IStreamingDevice device, string reason)
    {
        foreach (var channel in ChannelsToRelease(device))
        {
            UnsubscribeChannel(channel);
        }

        Disconnect(device);

        LastDisconnectReason = reason;
        NotifyConnection = true;
    }

    /// <summary>
    /// The channels teardown has to release: the entries the logger is actually still holding for
    /// <paramref name="device"/>.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Asks the LOGGER what it is holding rather than asking the device what it owns, because only
    /// the first question can be answered atomically. <c>DataChannels</c> is a plain <c>List</c>
    /// that Core's background events rebuild wholesale (<c>Clear</c> then <c>AddRange</c>), so a
    /// copy of it can legitimately come back short — or empty — without throwing anything, and
    /// every channel missed that way stays in the logger marked active for the process lifetime,
    /// still counting toward <c>CanToggleLogging</c>. That is the leak this whole class now exists
    /// to close, reintroduced through a race. <c>SubscribedChannels</c> has no such window: it is
    /// published copy-on-write, so a reader always gets a complete, immutable list.
    /// </para>
    /// <para>
    /// Matching is by serial number, ordinally — serials are opaque identifiers, and it is the same
    /// discriminator <c>LoggingManager.Unsubscribe</c> resolves by. A device with no serial number
    /// cannot be matched that way (a blank serial would sweep up every other unidentified device's
    /// channels), so that case alone falls back to the device's own list, best-effort and guarded:
    /// this runs inside an action posted to the dispatcher, and an escaping exception would take the
    /// whole teardown with it and leave the device connected, with nothing to catch it.
    /// </para>
    /// </remarks>
    private List<IChannel> ChannelsToRelease(IStreamingDevice device)
    {
        try
        {
            var serialNumber = device.DeviceSerialNo;
            if (!string.IsNullOrWhiteSpace(serialNumber))
            {
                return SubscribedChannels()
                    .Where(c => string.Equals(c.DeviceSerialNo, serialNumber, StringComparison.Ordinal))
                    .ToList();
            }

            return device.DataChannels?.ToList() ?? [];
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Warning(
                ex,
                $"Could not determine which channels belong to {device.DeviceDisplayName} while " +
                "tearing it down after a dropped connection; disconnecting it anyway.");
            return [];
        }
    }

    /// <summary>
    /// Reports a failure Core caught on one of a device's background threads. Without it a read
    /// loop that could not read and a decoder that could not decode both present to the user as a
    /// device that has simply stopped sending.
    /// </summary>
    /// <remarks>
    /// Observability only: Core does not tear the connection down for these, and neither does this
    /// handler. A genuinely dead link arrives separately as <see cref="IDevice.ConnectionLost"/>,
    /// which is where teardown and the user-facing notification live. No dispatcher hop either —
    /// nothing here touches bound state, and Core raises from a background thread.
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.OnDeviceErrorOccurred
    private void OnDeviceErrorOccurred(object? sender, CoreDeviceErrorEventArgs e)
    {
        // Core already collapses repeats per (source, exception type) and reports how many it
        // swallowed, so this reports the count instead of adding a second throttle on top.
        var suppressed = e.SuppressedCount > 0
            ? $"; {e.SuppressedCount} further like failure(s) suppressed by Core's throttle"
            : string.Empty;
        var message =
            $"Device {DescribeDevice(sender)} reported a background failure from {e.Source} " +
            $"({e.Error.GetType().Name}: {e.Error.Message}){suppressed}.";

        if (IsAppBug(e.Source))
        {
            AppLogger.Instance.Error(e.Error, message);
            return;
        }

        AppLogger.Instance.Warning(e.Error, message);
    }

    /// <summary>
    /// Decides whether a background device failure is an app bug (log at Error, which captures to
    /// Sentry) or an environmental condition (log at Warning, which does not).
    /// </summary>
    /// <remarks>
    /// <para>
    /// Routing environmental conditions to Error has burned the upstream app three times: the noise
    /// buries real bugs and the volume tracks how often users unplug things. So the sources that
    /// describe the link are all Warnings:
    /// </para>
    /// <list type="bullet">
    /// <item><description>
    /// <c>MessageConsumer</c> — a failed transport read, parse, or subscriber dispatch. The
    /// dominant cause by far is a link that is dying or gone, which Core independently escalates to
    /// <c>ConnectionStatus.Lost</c>; every unplug would otherwise file a Sentry event. Core does not
    /// separate the subscriber-dispatch subcase (which would be an app bug), so that one is
    /// knowingly under-reported here rather than paying for it with a flood — it is still written to
    /// the app log with its stack trace.
    /// </description></item>
    /// <item><description>
    /// <c>StreamDecode</c> — one malformed streaming frame. Core drops the frame and the stream
    /// survives, so this is firmware or link noise, not an app fault.
    /// </description></item>
    /// <item><description>
    /// <c>Reconnect</c> — Core exhausted its reconnect attempts. Terminal, but the cause is a device
    /// that is unplugged, powered off, or off the network, and the user already gets the
    /// <see cref="IDevice.ConnectionLost"/> teardown and its notification.
    /// </description></item>
    /// </list>
    /// <para>
    /// <c>StatusNotification</c> is an app bug and is the one place this table diverges from
    /// upstream's. Upstream enumerates the Core 1.4.0 set, where that member did not exist, and its
    /// default arm silently routes it to Warning. Core 1.7.0 raises it for exactly one thing: a
    /// <c>StatusChanged</c> subscriber that threw while being notified of a connection transition.
    /// Every subscriber to that event is this app's own code, and the usual way one throws is a
    /// cross-thread mutation of bound state from Core's transport thread — a real defect in this
    /// repo's code, on the drop path, which is precisely where it is hardest to notice and most
    /// expensive to miss.
    /// </para>
    /// <para>
    /// <c>Unknown</c> is an app bug for the mirror-image reason: no Core path raises it, so seeing
    /// one means Core hit a failure it could not classify — expected volume zero, and worth a look.
    /// A source value this build does not recognise is a different thing (the app is behind Core,
    /// not the device misbehaving) and stays a Warning.
    /// </para>
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.IsAppBug
    internal static bool IsAppBug(DeviceErrorSource source) => source switch
    {
        DeviceErrorSource.Unknown => true,
        DeviceErrorSource.StatusNotification => true,
        DeviceErrorSource.MessageConsumer => false,
        DeviceErrorSource.StreamDecode => false,
        DeviceErrorSource.Reconnect => false,
        _ => false
    };

    /// <summary>
    /// Reports a command that never reached the device. Sending is fire-and-forget, so without this
    /// a failed write is indistinguishable from a delivered one and the app's idea of device state
    /// can silently diverge from the device's.
    /// </summary>
    /// <remarks>
    /// Always a Warning: a write fails because the port closed, the device went away, or the device
    /// stopped draining its receive buffer (<c>IsTimeout</c>) — all conditions of the link, not app
    /// bugs. The distinction is still logged because "busy device" and "gone device" are diagnosed
    /// differently.
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.OnDeviceSendFailed
    private void OnDeviceSendFailed(object? sender, CoreSendFailedEventArgs e)
    {
        var outcome = e.IsTimeout
            ? "timed out on the way to"
            : "failed to reach";
        AppLogger.Instance.Warning(
            e.Error,
            $"Command '{DescribeCommand(e.Message?.Data)}' {outcome} device {DescribeDevice(sender)} " +
            $"and was not delivered ({e.Error.GetType().Name}: {e.Error.Message}).");
    }

    /// <summary>
    /// Names the device a background failure came from, the way the user sees it in the UI.
    /// </summary>
    // @port: Daqifi.Desktop.ConnectionManager.DescribeDevice
    private static string DescribeDevice(object? sender) =>
        sender is IStreamingDevice device ? device.DeviceDisplayName : "(unknown)";

    /// <summary>
    /// Reduces a SCPI command to its verb — everything before the first space — for logging.
    /// </summary>
    /// <remarks>
    /// Arguments are dropped deliberately: <c>SYSTem:COMMunicate:LAN:PASs "..."</c> carries the
    /// user's WiFi password in plaintext, and the app log must never contain it. The verb alone
    /// answers the question a send failure raises — which command was lost.
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.DescribeCommand
    internal static string DescribeCommand(string? data)
    {
        if (string.IsNullOrWhiteSpace(data))
        {
            return "(empty)";
        }

        var trimmed = data.Trim();
        var firstSpace = trimmed.IndexOf(' ');
        var verb = firstSpace < 0 ? trimmed : trimmed[..firstSpace];

        // A malformed or oversized payload must not turn one failure into a wall of log.
        return verb.Length <= MAX_LOGGED_COMMAND_LENGTH ? verb : verb[..MAX_LOGGED_COMMAND_LENGTH] + "...";
    }
    #endregion

    /// <summary>
    /// True when <paramref name="device"/> is the device currently undergoing a firmware update. During
    /// an update the device's serial transport drops and re-enumerates as an expected part of the flash,
    /// and Core owns the reconnect — so the desktop's disconnect-detection paths must leave that device's
    /// connection untouched rather than disposing the Core device Core is reconnecting (issue #738).
    /// </summary>
    /// <remarks>
    /// The firmware flow always drives the exact connected instance, so reference equality is the primary
    /// (and normally sufficient) match. The fallback compares the serial number — a stable hardware
    /// identity — never the display <c>Name</c>, which is a mutable, non-unique user label and could make
    /// an unrelated same-named device's disconnect be wrongly skipped, leaving a zombie connection.
    /// </remarks>
    // @port: Daqifi.Desktop.ConnectionManager.IsDeviceBeingUpdated
    public bool IsDeviceBeingUpdated(IStreamingDevice device)
    {
        var updating = DeviceBeingUpdated;
        if (updating == null)
        {
            return false;
        }

        if (ReferenceEquals(updating, device))
        {
            return true;
        }

        return !string.IsNullOrWhiteSpace(updating.DeviceSerialNo)
            && DeviceSerials.SameDevice(updating.DeviceSerialNo, device.DeviceSerialNo);
    }

    /// <summary>
    /// Marshals a UI-state change onto the UI thread from a device callback, without letting a
    /// dispatcher that is shutting down escape back into the caller.
    /// </summary>
    /// <remarks>
    /// <see cref="Dispatcher.Post"/> can throw once the dispatcher is going away, and this runs on
    /// Core's transport thread. Same reasoning, and the same shape, as <c>BootloaderWatcher</c>'s UI
    /// marshal: if the dispatcher is gone the update is simply dropped, which is the right outcome
    /// at shutdown.
    /// </remarks>
    private static void PostToUiThread(Action action)
    {
        if (Dispatcher.UIThread.CheckAccess())
        {
            action();
            return;
        }

        try
        {
            Dispatcher.UIThread.Post(action);
        }
        catch (Exception)
        {
            // Dispatcher unavailable / shutting down — drop the UI update.
        }
    }

    /// <summary>
    /// Checks if a device is already connected by comparing serial numbers.
    /// </summary>
    /// <param name="newDevice">The device to check for duplicates</param>
    /// <returns>
    /// The match, or <c>null</c> when <paramref name="newDevice"/> is not a duplicate. Absence is
    /// the answer rather than a flag on a result object, so "this is a duplicate" and "this is the
    /// device it duplicates" cannot disagree.
    /// </returns>
    // @port: Daqifi.Desktop.ConnectionManager.CheckForDuplicateDevice
    private DuplicateDeviceCheckResult? CheckForDuplicateDevice(IStreamingDevice newDevice)
    {
        // Match on Core's transport-independent DeviceIdentity (issue #752): it compares the serial
        // number first and falls back to the MAC address when the serial is blank — the WiFi path knows
        // a device's MAC before its serial arrives with the first status message, a case the previous
        // serial-only comparison could not detect at all. A serial mismatch is decisive, so the weaker
        // MAC discriminator can never merge two genuinely different units.
        var candidateIdentity = DeviceIdentity.Create(newDevice.DeviceSerialNo, newDevice.MacAddress);

        // With no discriminator at all there is nothing to compare against, so duplicates are undetectable.
        if (candidateIdentity.IsEmpty)
        {
            AppLogger.Instance.Information(
                $"Device {newDevice.Name} has no serial number or MAC address - cannot check for duplicates");
            return null;
        }

        var existingDevice = ConnectedDevices.FirstOrDefault(d =>
            DeviceIdentity.Create(d.DeviceSerialNo, d.MacAddress).Matches(candidateIdentity));

        if (existingDevice == null)
        {
            return null;
        }

        var newDeviceInterface = newDevice.ConnectionType == ConnectionType.Usb ? "USB" : "WiFi";
        var existingDeviceInterface = existingDevice.ConnectionType == ConnectionType.Usb ? "USB" : "WiFi";

        AppLogger.Instance.Information(
            $"Duplicate device detected ({candidateIdentity}): Device already connected via " +
            $"{existingDeviceInterface}, attempted to add via {newDeviceInterface}");

        return new DuplicateDeviceCheckResult(
            existingDevice, existingDeviceInterface, newDevice, newDeviceInterface);
    }
}

/// <summary>
/// A device that is already connected under the same identity, and how each side is attached.
/// </summary>
/// <remarks>
/// Only ever constructed when there IS a duplicate — <see cref="ConnectionManager"/>'s check returns
/// <c>null</c> otherwise — so it carries no "is this a duplicate" flag that could disagree with the
/// device it names, and every member is set by the one constructor rather than left to an object
/// initializer that may or may not fill it in.
/// </remarks>
/// <param name="ExistingDevice">The connected device the new one matches.</param>
/// <param name="ExistingDeviceInterface">How the already-connected device is attached ("USB"/"WiFi").</param>
/// <param name="NewDevice">The device being added.</param>
/// <param name="NewDeviceInterface">How the device being added is attached ("USB"/"WiFi").</param>
// @port: Daqifi.Desktop.DuplicateDeviceCheckResult
public sealed record DuplicateDeviceCheckResult(
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.ExistingDevice
    IStreamingDevice ExistingDevice,
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.ExistingDeviceInterface
    string ExistingDeviceInterface,
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.NewDevice
    IStreamingDevice NewDevice,
    // @port: Daqifi.Desktop.DuplicateDeviceCheckResult.NewDeviceInterface
    string NewDeviceInterface);

/// <summary>
/// Actions that can be taken when a duplicate device is detected
/// </summary>
// @port: Daqifi.Desktop.DuplicateDeviceAction
public enum DuplicateDeviceAction
{
    KeepExisting,
    SwitchToNew,
    Cancel
}

/// <summary>
/// What one <see cref="ConnectionManager.Connect"/> call did, and which device it did it to.
/// </summary>
/// <remarks>
/// Immutable and returned by value, so it cannot be overwritten by a connect that finishes later —
/// which is the whole point of it existing. No app-level type without this shape can answer "did
/// the device I just pressed Connect on actually connect?" while another attempt is in flight.
/// </remarks>
/// <param name="Device">The device this call was given.</param>
/// <param name="Status">The terminal status that attempt reached.</param>
public sealed record ConnectionAttemptResult(IStreamingDevice Device, DAQiFiConnectionStatus Status)
{
    /// <summary>
    /// True when the user ended up with a connected device.
    /// </summary>
    /// <remarks>
    /// <see cref="DAQiFiConnectionStatus.AlreadyConnected"/> counts as success and always has: the
    /// user asked for a connected device and has one, so the dialog closes rather than showing an
    /// error over a device sitting in the device list.
    /// </remarks>
    public bool IsConnected =>
        Status is DAQiFiConnectionStatus.Connected or DAQiFiConnectionStatus.AlreadyConnected;

    /// <summary>
    /// True when the attempt ended because the user called it off, not because anything failed:
    /// the only way <see cref="ConnectionManager.Connect"/> reports
    /// <see cref="DAQiFiConnectionStatus.Disconnected"/> is <see cref="DuplicateDeviceAction.Cancel"/>
    /// from the duplicate-device prompt (dismissing it counts).
    /// </summary>
    /// <remarks>
    /// Worth a name of its own because it is neither outcome the caller would otherwise guess at.
    /// Telling the user "could not connect" after they pressed Cancel blames the hardware for their
    /// own decision, and closing the dialog on it acts on a connect they declined.
    /// </remarks>
    public bool WasCancelledByUser => Status is DAQiFiConnectionStatus.Disconnected;
}

// @port: Daqifi.Desktop.DAQiFiConnectionStatus
public enum DAQiFiConnectionStatus
{
    Disconnected,
    Connecting,
    Connected,
    Error,
    AlreadyConnected
}
